-- 1. Add difficulty column to sentences
ALTER TABLE sentences ADD COLUMN IF NOT EXISTS difficulty text CHECK (difficulty IN ('easy', 'medium', 'hard'));

-- 2. Populate difficulty values
UPDATE sentences SET difficulty = CASE id
  WHEN 1 THEN 'easy'
  WHEN 2 THEN 'medium'
