-- 3. Add preferred_difficulties to users table
ALTER TABLE users ADD COLUMN IF NOT EXISTS preferred_difficulties text[] NOT NULL DEFAULT '{}' ;

-- 4. Update get_random_sentences to filter by difficulty
CREATE OR REPLACE FUNCTION get_random_sentences(
  p_user_id uuid,
  p_categories text[],
  p_difficulties text[],
  p_limit int
)
RETURNS SETOF sentences
LANGUAGE sql
STABLE
AS $$
  SELECT s.*
  FROM sentences s
  WHERE
    (array_length(p_categories, 1) IS NULL OR s.category = ANY(p_categories))
    AND (array_length(p_difficulties, 1) IS NULL OR s.difficulty = ANY(p_difficulties))
    AND s.id NOT IN (
      SELECT sentence_id FROM user_progress WHERE user_id = p_user_id
    )
  ORDER BY RANDOM()
  LIMIT p_limit;
$$;
